{
    "terms": {
        "title": "Terms of Service",
        "subtitle": "This User Agreement governs your use of the BitTasker platform.",
        "last_updated": "Last Updated: July 13, 2025",
        "intro": "By accessing or using the BitTasker platform, you agree to be bound by these Terms of Service, our <a href=\"/privacy\" class=\"link link-primary\">Privacy Policy</a>, and all applicable laws and regulations. If you do not agree with any part of these terms, you may not use our services.",
        "definitions": {
            "title": "Definitions",
            "intro": "Throughout these Terms of Service, when we say:",
            "bitTasker": "<strong>\"BitTasker,\"</strong> \"we,\" \"us,\" or \"our\" refers to BitTasker, the company that develops and maintains the BitTasker platform.",
            "services": "<strong>\"Services\"</strong> refers to the features and functions provided by the BitTasker platform.",
            "platform": "<strong>\"Platform\"</strong> refers to our website, mobile applications, and other related services.",
            "user": "<strong>\"User,\"</strong> \"you,\" or \"your\" refers to individuals who use our platform in any capacity.",
            "tasker": "<strong>\"Tasker,\"</strong> refers to users who post tasks requesting services.",
            "taskee": "<strong>\"Taskee\"</strong> refers to users who offer to perform services for Taskers.",
            "task_contract": "<strong>\"Task Contract\"</strong> refers to the agreement formed between a Tasker and a Taskee when an offer is accepted.",
            "nostr": "<strong>\"Nostr\"</strong> refers to the decentralized protocol that powers communications and identity on the BitTasker platform.",
            "bitcoin": "<strong>\"Bitcoin\"</strong> refers to the cryptocurrency used for payments on the BitTasker platform, including on-chain, Lightning Network, and Liquid Network transactions.",
            "service_fee": "<strong>\"Service Fee\"</strong> refers to the fee BitTasker charges for facilitating connections between Taskers and Taskees."
        },
        "scope": {
            "title": "1. Scope of BitTasker Services",
            "subsection": "",
            "point1": "BitTasker provides a decentralized platform that enables Taskers to publish task requests and Taskees to make offers to complete these tasks.",
            "point2": "The platform uses the Nostr protocol for identity, data storage, and communications, with Bitcoin and fiat as payment methods.",
            "point3": "When a Tasker accepts a Taskee's offer, a Task Contract is created directly between these parties.",
            "point4": "Upon task completion and confirmation, funds are released from escrow to the Taskee.",
            "point5": "Both parties are encouraged to review and provide feedback after task completion, to help the community."
        },
        "role": {
            "title": "2. BitTasker's Role and Obligations",
            "point1": "BitTasker provides the platform and technical infrastructure that enables the connection between Taskers and Taskees.",
            "point2": "BitTasker only permits individuals over 18 years of age to become Users.",
            "point3": "BitTasker may refuse service or suspend accounts of users who violate these terms.",
            "point4": "As a decentralized application:",
            "point4a": "BitTasker does not store your private keys or have access to your encrypted messages.",
            "point4b": "BitTasker cannot recover lost keys or passwords.",
            "point4c": "BitTasker does not have the ability to reverse, or intervene, in transactions.",
            "point5": "BitTasker accepts no liability for any aspect of the interaction between Taskers and Taskees, including but not limited to the description, performance, or delivery of services.",
            "point6": "BitTasker is not responsible for and does not warrant the truth or accuracy of any information provided by Users.",
            "point7": "The platform is provided \"as is\" and without any warranty or condition, express or implied."
        },
        "user": {
            "title": "3. User Obligations",
            "intro": "You will at all times:",
            "point1": "Comply with these Terms of Service and all applicable laws and regulations.",
            "point2": "Only post accurate information on the BitTasker platform.",
            "point3": "Be aware of and comply with any laws that apply to you as a Tasker or Taskee.",
            "point4": "Be responsible for the security of your own Nostr private keys and Bitcoin wallet.",
            "point5": "Not use the BitTasker platform for any illegal or immoral purpose.",
            "point6": "Not allow others to use your account or transfer your account to another person.",
            "subintro": "Any information you post on the BitTasker platform must not:",
            "subpoint1": "Be false, inaccurate, misleading, or deceptive.",
            "subpoint2": "Be fraudulent or involve counterfeit or stolen items.",
            "subpoint3": "Infringe on any third party's intellectual property rights.",
            "subpoint4": "Violate any applicable laws or regulations.",
            "subpoint5": "Be defamatory, libelous, threatening, or harassing.",
            "subpoint6": "Contain obscene or inappropriate material.",
            "subpoint7": "Contain malicious code that could harm the platform or other users."
        },
        "bitcoin": {
            "title": "4. Bitcoin Payments",
            "point1": "Users acknowledge that Bitcoin transactions are irreversible and BitTasker cannot recover funds sent to incorrect addresses.",
            "point2": "BitTasker uses multi-signature escrow for task payments to provide security for both parties.",
            "point3": "When a Task Contract is created, the Tasker must deposit the agreed amount into escrow.",
            "point4": "Service Fees are deducted from the task payment when funds are released from escrow.",
            "point5": "Bitcoin price volatility: Both parties acknowledge that the value of Bitcoin can fluctuate and agree that once a price is set in Bitcoin for a task, it will not be adjusted due to price fluctuations.",
            "point6": "Users are responsible for any taxes or regulatory compliance related to their transactions."
        },
        "fees": {
            "title": "5. Dynamic Fee Structure",
            "point1": "BitTasker implements a level-based system that rewards active users with benefits.",
            "point2": "Users can earn levels by successfully completing tasks (as Taskees) or hiring Taskees (as Taskers).",
            "point3": "Higher levels may result in reduced Service Fees and additional platform privileges.",
            "point4": "The dynamic fee structure is designed to reward repeat business and active platform participation.",
            "point5": "BitTasker reserves the right to modify the fee structure at any time."
        },
        "encryption": {
            "title": "6. End-to-End Encryption and Privacy",
            "point1": "All direct messages between users are end-to-end encrypted.",
            "point2": "BitTasker cannot access the content of your private conversations.",
            "point3": "Users are responsible for maintaining the security of their private keys.",
            "point4": "If you lose access to your private keys, BitTasker cannot recover your encrypted messages or account.",
            "point5": "For more details on our privacy practices, please see our",
            "privacy_link": "Privacy Policy"
        },
        "language": {
            "title": "7. Multi-Language Support",
            "point1": "BitTasker offers automatic translation features to facilitate communication between users who speak different languages.",
            "point2": "While we strive for accuracy, users acknowledge that automatic translations may not be perfect and could sometimes lead to misunderstandings.",
            "point3": "In case of any discrepancy between different language versions of these Terms, the English version shall prevail.",
            "point4": "To avoid any confusion, it is recommended to be as clear as possible in communications."
        },
        "disputes": {
            "title": "8. Dispute Resolution",
            "point1": "In the event of a dispute between a Tasker and a Taskee, both parties must attempt to resolve the issue directly through the platform's messaging system.",
            "point2": "If the parties cannot reach a resolution, our escrow system will be used to resolve the dispute.",
            "point3": "Escrow is implemented with 2:2 multisig wallets where only the tasker and taskee have the keys.",
            "point4": "Since BitTasker does not have access to your funds, we are unable to intervene in the event that a tasker and taskee have a dispute.",
            "point5": "See our detailed",
            "escrow_link": "escrow page"
        },
